const out = [];
for (const item of $input.all()) {
  const title = String(item.json.title || '').trim();
  const body = String(item.json.body || '').trim();
  const prompt = [
    'Ты классификатор GitHub Issues в учебном проекте.',
    'Определи тип обращения и уверенность в ответе.',
    '',
    'Типы:',
    '- bug   — ошибка, что-то сломано, не работает, падает, неверный результат',
    '- task  — задача, доработка, рефакторинг, документация, процесс без новой функциональности',
    '- feature — новая функциональность или заметное улучшение продукта',
    '',
    'Правила:',
    '- Если описание расплывчатое и тип не ясен (например «что-то не так», «надо обсудить»), ставь confidence ниже 0.8.',
    '- Если по тексту очевидно, какой это тип, ставь confidence 0.9-0.99.',
    '- confidence — это число от 0 до 1, отражающее уверенность в выбранном типе.',
    '',
    '=== ЗАГОЛОВОК ISSUE ===',
    title,
    '',
    '=== ОПИСАНИЕ ISSUE ===',
    body,
  ].join(String.fromCharCode(10));

  out.push({ json: { title: title, body: body, prompt: prompt } });
}
return out;

const allowed = ['bug', 'task', 'feature'];
const out = [];
for (const item of $input.all()) {
  const raw = item.json.output !== undefined ? item.json.output : item.json;
  let type = '';
  let confidence = 0;
  if (raw && typeof raw === 'object') {
    type = String(raw.type || '').trim().toLowerCase();
    confidence = Number(raw.confidence);
  } else if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      type = String(parsed.type || '').trim().toLowerCase();
      confidence = Number(parsed.confidence);
    } catch (e) {}
  }
  if (!allowed.includes(type)) {
    type = 'unknown';
    confidence = 0;
  }
  if (!isFinite(confidence)) confidence = 0;
  if (confidence > 1) confidence = confidence / 100;
  if (confidence < 0) confidence = 0;
  if (confidence > 1) confidence = 1;
  out.push({ json: { type: type, confidence: Math.round(confidence * 100) / 100 } });
}
return out;
